'AC-reporting.income-statement.1'; from decimal import Decimal; import pytest; from src.reporting.base.income_statement_calculator import calculate_income_statement_totals, calculate_line_total; pytestmark = pytest.mark.no_db
def test_positive_net_income(): 'AC-reporting.income-statement.1'; income_lines = [{'name': 'Consulting Revenue', 'amount': Decimal('5000.00')}, {'name': 'Interest Income', 'amount': Decimal('250.50')}]; expense_lines = [{'name': 'Office Rent', 'amount': Decimal('1500.00')}, {'name': 'Cloud Subscriptions', 'amount': Decimal('350.25')}]; totals = calculate_income_statement_totals(income_lines, expense_lines); assert totals.total_income == Decimal('5250.50'); assert totals.total_expenses == Decimal('1850.25'); assert totals.net_income == Decimal('3400.25'); 'AC-reporting.income-statement.1'; 'AC-reporting.income-statement.1'; _m1_income_lines = [{'name': 'Sales', 'amount': Decimal('1200.00')}]; _m1_expense_lines = [{'name': 'COGS', 'amount': Decimal('1500.00')}, {'name': 'Shipping', 'amount': Decimal('300.00')}]; _m1_totals = calculate_income_statement_totals(_m1_income_lines, _m1_expense_lines); assert _m1_totals.total_income == Decimal('1200.00'); assert _m1_totals.total_expenses == Decimal('1800.00'); assert _m1_totals.net_income == Decimal('-600.00'); 'AC-reporting.income-statement.1'; 'AC-reporting.income-statement.1'; _m2_totals = calculate_income_statement_totals([], []); assert _m2_totals.total_income == Decimal('0.00'); assert _m2_totals.total_expenses == Decimal('0.00'); assert _m2_totals.net_income == Decimal('0.00'); _m3_lines = [{'amount': '100.55'}, {'amount': Decimal('200.45')}]; assert calculate_line_total(_m3_lines) == Decimal('301.00'); _m4_income = [{'amount': Decimal('1000.00')}]; _m4_expenses = [{'amount': Decimal('400.00')}]; _m4_base = calculate_income_statement_totals(_m4_income, _m4_expenses); _m4_mutated_expenses = [{'amount': Decimal('450.00')}]; _m4_mutated = calculate_income_statement_totals(_m4_income, _m4_mutated_expenses); assert _m4_mutated.net_income == _m4_base.net_income - Decimal('50.00')
